-- cortex.required_extensions: what the database must have installed for this schema (an extension, a plugin), in order. Owner: cortex.
CREATE TABLE cortex.required_extensions (
  id              BIGINT NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,                                  -- issued by the database
  design          UUID NOT NULL REFERENCES cortex.designs (id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,  -- the design that needs it
  name            TEXT NOT NULL CHECK (length(name) >= 1),                                                       -- its name, in the engine's words (postgis)
  namespace_name  TEXT,                                                                                          -- the namespace it is installed into, as the server names it; NULL for the engine's default
  version         TEXT,                                                                                          -- the version installed; NULL for the newest
  position        NUMERIC NOT NULL CHECK (position > 0),                                                         -- its place in the design's list of requirements; an order key
  UNIQUE (design, name) DEFERRABLE INITIALLY DEFERRED,
  UNIQUE (design, position) DEFERRABLE INITIALLY DEFERRED
);

COMMENT ON TABLE cortex.required_extensions IS 'what the database must have installed for this schema (an extension, a plugin), in order.';
COMMENT ON COLUMN cortex.required_extensions.id IS 'issued by the database';
COMMENT ON COLUMN cortex.required_extensions.design IS 'the design that needs it';
COMMENT ON COLUMN cortex.required_extensions.name IS 'its name, in the engine''s words (postgis)';
COMMENT ON COLUMN cortex.required_extensions.namespace_name IS 'the namespace it is installed into, as the server names it; NULL for the engine''s default';
COMMENT ON COLUMN cortex.required_extensions.version IS 'the version installed; NULL for the newest';
COMMENT ON COLUMN cortex.required_extensions.position IS 'its place in the design''s list of requirements; an order key';
